package com.ebuddy.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="message_outbox") public class OutboxEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="outbox_id") Long id; @Column(name="message_id",nullable=false) UUID messageId; @Column(name="event_type",nullable=false) String eventType; @Enumerated(EnumType.STRING) @Column(nullable=false) OutboxState state=OutboxState.pending; @Column(nullable=false) int attempts; @Column(name="available_at",nullable=false) Instant availableAt=Instant.now(); @Column(name="created_at",nullable=false) Instant createdAt=Instant.now(); protected OutboxEntity(){} public OutboxEntity(UUID m,String t){messageId=m;eventType=t;} public UUID getMessageId(){return messageId;} public String getEventType(){return eventType;} public OutboxState getState(){return state;} public void done(){state=OutboxState.done;} public void retry(){attempts++;} }
